// ---- Client -> agent (stdin) ----

/** What the user has open in the editor, sent with a message. */
export interface IdeContext {
  active_file?: string | null;
  selection?: IdeSelection | null;
  diagnostics?: IdeDiagnostic[];
}

export interface IdeDiagnostic {
  path: string;
  line: number;
  severity: "error" | "warning" | "info" | "hint";
  message: string;
  source?: string | null;
}

export interface IdeSelection {
  path: string;
  start_line: number;
  end_line: number;
  text: string;
}

/**
 * A tool the IDE itself defines, for the model to call (VS Code's built-in browser
 * tools, found at run time): its name, what it does, and its inputs as a JSON schema.
 * cmcoder offers it as it is and relays each call with `ide_tool_request`.
 */
export interface IdeToolDef {
  name: string;
  description?: string;
  input_schema?: Record<string, unknown>;
}

/**
 * An image the user pasted, dropped or picked. cmcoder checks the bytes
 * (PNG, JPEG, GIF or WebP only) and makes a large one smaller.
 */
export interface ImageAttachment {
  data: string;
  media_type?: string | null;
  name?: string | null;
}

/** Start a turn. Only one turn runs at a time. */
export interface UserMessage {
  type: "user_message";
  text?: string;
  context?: IdeContext | null;
  images?: ImageAttachment[];
}

/** Stop the running turn (like Ctrl+C in the CLI). */
export interface Interrupt {
  type: "interrupt";
}

/** The answer to a `permission_request`. */
export interface PermissionResponse {
  type: "permission_response";
  request_id: string;
  allow: boolean;
  remember?: boolean;
  remember_session?: boolean;
  feedback?: string | null;
}

/**
 * Stop one running tool call (Bash) and let the turn go on: the model is told the
 * user stopped it. `interrupt` stops the whole turn instead.
 */
export interface StopTool {
  type: "stop_tool";
  tool_use_id: string;
}

export interface SetMode {
  type: "set_mode";
  mode: string;
}

export interface SetModel {
  type: "set_model";
  model: string;
}

/**
 * Talk to one of the agents in `agent_list` for the rest of the conversation (its
 * instructions, tools and model replace the default's), or `agent: null` for the default.
 * Refused during a turn. Answered with `agent_changed`.
 */
export interface SetAgent {
  type: "set_agent";
  agent?: string | null;
}

/**
 * The client can run these IDE tools (e.g. getDiagnostics, openFile).
 *
 * Send once after `system_init` (and again when the list changes, before a turn); the
 * agent offers them to the model and asks the client to run them with `ide_tool_request`.
 * `tools`: tools cmcoder knows by name; `tool_defs`: tools only the IDE knows (their
 * schemas come with them).
 */
export interface IdeCapabilities {
  type: "ide_capabilities";
  tools: string[];
  tool_defs?: IdeToolDef[];
}

/** The answer to an `ide_tool_request`. */
export interface IdeToolResult {
  type: "ide_tool_result";
  request_id: string;
  content: string;
  is_error?: boolean;
  images?: string[];
}

/** Ask for this project's saved conversations (answered with `session_list`). */
export interface ListSessions {
  type: "list_sessions";
}

/**
 * Ask for the slash commands (answered with `command_list`). A
 * `user_message` whose text starts with one of them runs it.
 */
export interface ListCommands {
  type: "list_commands";
}

/**
 * Go back to before user message `turn` (from `rewind_points`): undo the
 * agent's file changes (`code`), the conversation, or both. Files outside the
 * project are only restored with `outside`.
 */
export interface Rewind {
  type: "rewind";
  turn: number;
  code?: boolean;
  conversation?: boolean;
  outside?: boolean;
}

/**
 * Code search: the index's state, or update / rebuild / clear it. Answered
 * with `index_status` (and `index_progress` while it works).
 */
export interface Index {
  type: "index";
  action?: "status" | "update" | "rebuild" | "clear";
}

/** The gateways' models, for picking an embedding model (`rag_candidates`). */
export interface RagCandidates {
  type: "rag_candidates";
}

/** Set up code search, as `cmcoder rag setup` does (`rag_setup_result`). */
export interface RagSetup {
  type: "rag_setup";
  embedding_model: string;
  store?: "local" | "lancedb" | "chroma-server";
  url?: string | null;
  api_key?: string | null;
  scope?: "user" | "project";
  read_only?: boolean;
  index_now?: boolean;
}

/**
 * Stop one subagent (a `subagent_status` id); the turn and the other
 * subagents go on. It writes a report of what it found so far.
 */
export interface StopSubagent {
  type: "stop_subagent";
  id: string;
}

/**
 * Switch critique on or off (the panel's checkbox). `save`: also save it
 * as `critic.enabled` in the user's settings, which every running cmcoder
 * follows (the terminal, the TUI, other VS Code windows).
 */
export interface SetCritique {
  type: "set_critique";
  enabled: boolean;
  save?: boolean;
}

/** Stop the running turn, save the session and exit (EOF does the same). */
export interface Shutdown {
  type: "shutdown";
}

export type ClientMessage =
  | UserMessage
  | Interrupt
  | PermissionResponse
  | StopTool
  | SetMode
  | SetModel
  | SetAgent
  | IdeCapabilities
  | IdeToolResult
  | ListSessions
  | ListCommands
  | Rewind
  | Index
  | RagCandidates
  | RagSetup
  | StopSubagent
  | SetCritique
  | Shutdown;
